import{_ as o,o as t,c as n,a2 as a}from"./chunks/framework.CHeM0PsO.js";const g=JSON.parse('{"title":"Design System & Branding","description":"","frontmatter":{"epic":7,"title":"Design System & Branding","status":"✅ Done","scope":"mobile","sourceUrl":"https://github.com/sovereignfs/sovereign-edge/blob/main/docs/epics/mobile/design-system.md"},"headers":[],"relativePath":"sovereign-edge/epics/mobile/design-system.md","filePath":"sovereign-edge/epics/mobile/design-system.md"}'),s={name:"sovereign-edge/epics/mobile/design-system.md"};function i(c,e,r,d,l,h){return t(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="epic-design-system-branding" tabindex="-1">Epic: Design System &amp; Branding <a class="header-anchor" href="#epic-design-system-branding" aria-label="Permalink to &quot;Epic: Design System &amp; Branding&quot;">​</a></h1><blockquote><p>A native RN theme adapting Sovereign&#39;s visual identity — the app is fully standalone, but may look and feel like part of the same family.</p></blockquote><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Per the developer&#39;s decision in research 0001: Sovereign Edge is a fully independent app with no runtime dependency on <code>sovereign</code>, but may reuse Sovereign&#39;s visual identity. <code>@sovereignfs/ui</code> itself (CSS Modules + web React components) isn&#39;t usable in React Native directly — this epic is about porting the <em>token values and visual language</em> (monochrome identity, the <code>--sv-*</code> scale) into a native theme system, not importing the web package.</p><h2 id="tasks" tabindex="-1">Tasks <a class="header-anchor" href="#tasks" aria-label="Permalink to &quot;Tasks&quot;">​</a></h2><h4 id="✅-7-1-—-native-theme-tokens" tabindex="-1">✅ 7.1 — Native theme tokens <a class="header-anchor" href="#✅-7-1-—-native-theme-tokens" aria-label="Permalink to &quot;✅ 7.1 — Native theme tokens&quot;">​</a></h4><p><strong>Goal:</strong> Port Sovereign&#39;s token values (spacing, radius, font-size scale, monochrome color identity) into an RN-native theme (e.g. a plain TS theme object / RN StyleSheet constants), without importing <code>@sovereignfs/ui</code> itself.</p><p><strong>Deliverables:</strong></p><ul><li>A theme module mirroring <code>sovereign</code>&#39;s primitive/semantic two-tier token structure conceptually, values ported by hand rather than shared at the code level.</li><li>Light/dark mode support, matching Sovereign&#39;s existing dark-mode override pattern.</li></ul><p><strong>Dependencies:</strong> none within this epic.</p><p><strong>Review checklist:</strong></p><ul><li>✅ Switching light/dark mode restyles the whole app from the semantic theme layer, with no per-component hardcoded colors. Verified on an Android emulator by toggling the system setting (<code>cmd uimode night yes</code>) without restarting the app: the surface inverted from white to <code>#09090b</code> and body text from grey-950 to grey-50, driven entirely by the semantic tier. <code>App.tsx</code> keeps only layout in <code>StyleSheet</code>; every colour and type value comes from <code>useTheme()</code>.</li></ul><hr><h4 id="✅-7-2-—-core-component-set" tabindex="-1">✅ 7.2 — Core component set <a class="header-anchor" href="#✅-7-2-—-core-component-set" aria-label="Permalink to &quot;✅ 7.2 — Core component set&quot;">​</a></h4><p><strong>Goal:</strong> The minimum native component set the chat and settings UI need.</p><p><strong>Deliverables:</strong></p><ul><li>Button, input, chat bubble, list item, toggle, and similar primitives built on Task 7.1&#39;s theme, styled consistently with the wider Sovereign identity without being the same code.</li></ul><p><strong>Dependencies:</strong> Task 7.1.</p><p><strong>Review checklist:</strong></p><ul><li>✅ No screen in the app hardcodes a color, spacing, or radius value outside the theme module. Enforced by lint rather than inspection: <code>eslint.config.js</code> rejects hex/<code>rgb()</code>/<code>hsl()</code> literals anywhere under <code>src/</code> except <code>src/design-system/</code>, where defining them is the job. Verified the rule fires by planting a violation, not just by seeing it pass.</li></ul><p><strong>Known deviation:</strong> <code>Toggle</code> wraps the platform <code>Switch</code> and is deliberately untinted, so it shows the OS accent rather than Sovereign&#39;s monochrome one. Two attempts to theme it were worse: Android alpha-blends <code>trackColor</code>, which made a near-white <code>accent</code> track invisible in dark mode, and it does not reliably honour <code>thumbColor</code> — leaving a white thumb on an invisible track. Platform colours are legible in both schemes; matching the identity here needs a custom Pressable-based toggle, not more props.</p><hr><h4 id="✅-7-3-—-warm-palette-shared-token-source-of-truth" tabindex="-1">✅ 7.3 — Warm palette + shared token source of truth <a class="header-anchor" href="#✅-7-3-—-warm-palette-shared-token-source-of-truth" aria-label="Permalink to &quot;✅ 7.3 — Warm palette + shared token source of truth&quot;">​</a></h4><p><strong>Goal:</strong> Give Sovereign Edge its own visual identity — distinct from Sovereign&#39;s cool monochrome — and stop hand-duplicating token values between <code>apps/mobile/src/design-system</code> and <code>packages/design-tokens</code>.</p><p><strong>Deliverables:</strong></p><ul><li>Warm <code>grey</code> neutral scale + a new <code>clay</code> accent scale in <code>packages/design-tokens/{primitives,semantic}.ts</code>, replacing Sovereign&#39;s monochrome identity. Values validated first, interactively, in <code>packages/design-tokens/reference.html</code> (light + dark, every screen mockup) before landing here.</li><li><code>fontFamily</code> updated to name Hanken Grotesk (body) / JetBrains Mono (code) — fallback stacks only, no font files bundled.</li><li><code>apps/mobile/src/design-system</code> consumes <code>packages/design-tokens</code> directly for colours and scale tokens instead of hand-copying them; its own <code>primitives.ts</code> is deleted. A trimmed local <code>semantic.ts</code> keeps only what genuinely can&#39;t be shared as-is: RN-shaped <code>Shadow</code>/<code>shadows()</code>, RN&#39;s bare-name <code>fontFamily</code>, and RN&#39;s string-literal <code>fontWeight</code>.</li></ul><p><strong>Dependencies:</strong> Tasks 7.1, 7.2.</p><p><strong>Review checklist:</strong></p><ul><li>✅ <code>pnpm --filter design-tokens typecheck</code>, <code>pnpm --filter mobile typecheck</code>, <code>pnpm --filter mobile lint</code> (the no-hardcoded-colour rule) all pass.</li><li>✅ <code>apps/mobile</code>&#39;s full test suite (338 tests, 35 suites) passes unchanged — the design-system tests assert theme <em>structure</em>, not literal colour values, so they exercise the new tokens without needing edits themselves.</li><li>✅ Verified on the iOS Simulator, both light and dark (Settings → Appearance): the warm cream surface and clay accent render on Chat&#39;s send button and Settings&#39; theme rows, matching <code>packages/design-tokens/reference.html</code> side by side.</li></ul><hr><h4 id="✅-7-4-—-icon-system" tabindex="-1">✅ 7.4 — Icon system <a class="header-anchor" href="#✅-7-4-—-icon-system" aria-label="Permalink to &quot;✅ 7.4 — Icon system&quot;">​</a></h4><p><strong>Goal:</strong> Replace the text-only tab bar (<code>RootNavigator.tsx</code>&#39;s explicit &quot;no icon set is chosen yet&quot; workaround) with a real, curated icon set.</p><p><strong>Deliverables:</strong></p><ul><li><code>react-native-svg</code> + <code>lucide-react-native</code> as dependencies — same icon library and visual language <code>sovereign</code> uses (<code>docs/design-system.md</code>&#39;s Icon system, RFC 0011), MIT/ISC licensed. <code>sovereign</code> ships a zero-runtime-dependency mechanism (inline SVGs generated at build time from a curated list); that specific mechanism is web/RSC-specific and doesn&#39;t carry over to React Native, which needs <code>react-native-svg</code> as a runtime SVG renderer regardless — so this wraps the official <code>lucide-react-native</code> package (same path data, same stroke conventions) instead of hand-porting individual icon paths.</li><li>A curated <code>Icon</code> component (<code>apps/mobile/src/design-system/components/ Icon.tsx</code>) mirroring Sovereign&#39;s own <code>&lt;Icon name size aria-hidden|aria- label&gt;</code> contract, bound to the existing <code>iconSize</code> scale tokens. <code>color</code> is a required prop (not defaulted or inherited via <code>currentColor</code>, which React Native&#39;s SVG renderer has no equivalent for) — every call site says explicitly which theme color it means.</li><li><code>RootNavigator</code> tab icons wired (<code>message-circle</code>/Chat, <code>cpu</code>/Models, <code>settings</code>/Settings — <code>cpu</code> chosen over a generic package icon as the same &quot;inference on your own silicon&quot; shorthand the app&#39;s mark uses); the <code>tabBarIcon: () =&gt; null</code> workaround removed.</li><li><code>apps/mobile/metro.config.js</code> (new file — this app previously ran on Expo&#39;s implicit default) and <code>jest.config.js</code>&#39;s <code>moduleNameMapper</code>, both routing <code>lucide-react-native</code> to its plain-CJS build (see review checklist below for why).</li></ul><p><strong>Dependencies:</strong> Task 7.3.</p><p><strong>Review checklist:</strong></p><ul><li>✅ <code>pnpm typecheck</code>, <code>pnpm lint</code> (no-hardcoded-colour rule), and the full test suite (338 tests, 35 suites) all pass.</li><li>✅ Both bundlers needed the same fix, for the same underlying reason: <code>lucide-react-native</code>&#39;s <code>&quot;react-native&quot;</code>/<code>&quot;import&quot;</code> export condition points at an ESM barrel (<code>dist/esm/lucide-react-native.mjs</code>) whose relative re-exports of <code>./icons/*.mjs</code> don&#39;t resolve cleanly through either tool. <code>jest.config.js</code>&#39;s <code>moduleNameMapper</code> and the new <code>metro.config.js</code>&#39;s <code>resolver.extraNodeModules</code> both route the bare <code>lucide-react-native</code> specifier straight to the package&#39;s plain-CJS build instead (same icon path data, same props) — Jest hit raw ESM <code>export</code> syntax without it; Metro&#39;s bundler hit an unresolvable nested <code>.mjs</code> import without it.</li><li>✅ Verified on the iOS Simulator, on-device (not just Metro serving a cached bundle): the tab bar shows the three Lucide icons (chat bubble, chip, gear), correctly tinted by <code>tabBarActiveTintColor</code>/ <code>tabBarInactiveTintColor</code> per tab and per scheme, confirmed in both light and dark.</li></ul><p><strong>Deferred to later tasks:</strong> the icon-less banners, mode chips, and provenance receipts on Chat (7.5), Models&#39; fit badges (7.6), and Connectors&#39; status pills (7.7) still need their own icon wiring — 7.4 only covers the tab bar and the reusable <code>Icon</code> component itself.</p><hr><h4 id="✅-7-5-—-chat-screen-icons-provenance-receipts-multiline-composer" tabindex="-1">✅ 7.5 — Chat screen: icons, provenance receipts, multiline composer <a class="header-anchor" href="#✅-7-5-—-chat-screen-icons-provenance-receipts-multiline-composer" aria-label="Permalink to &quot;✅ 7.5 — Chat screen: icons, provenance receipts, multiline composer&quot;">​</a></h4><p><strong>Goal:</strong> Bring the Chat screen up to <code>reference.html</code>&#39;s mockup: an icon-only send button, iconified offline/warning banners and mode chips, a real multiline composer, and — required by the concept paper&#39;s disclosure promise — a visible receipt on every reply that used a connector.</p><p><strong>Deliverables:</strong></p><ul><li>Circular icon send/stop button (<code>ComposerButton</code>), replacing the full-width text button — <code>send</code>/<code>square</code> icons, <code>accessibilityLabel</code> carrying the text a sighted user no longer sees.</li><li>Offline banner (<code>wifi-off</code>/<code>alert-triangle</code>), the risky-connector warning banner (<code>alert-triangle</code>), and mode chips (one icon per mode, from <code>MODE_ICON</code>) all gain icons alongside their existing text.</li><li>Composer&#39;s <code>TextField</code> gains a <code>multiline</code> prop: grows with content, capped at <code>touchTargetMin * 3</code> (~3 lines) via <code>maxHeight</code>, top-aligned text.</li><li>A new <code>Mark</code> component (<code>design-system/components/Mark.tsx</code>) — a hand-coded SVG of the app&#39;s &quot;one gate&quot; glyph, not from Lucide — renders in a connector-provenance receipt row below any assistant bubble whose message carries a <code>connector</code>, replacing the old inline &quot;via X&quot; text. Same glyph, same &quot;this crossed the boundary, with permission&quot; motif the app icon will use (task 7.8).</li></ul><p><strong>Dependencies:</strong> Task 7.4.</p><p><strong>Review checklist:</strong></p><ul><li>✅ <code>pnpm --filter mobile typecheck</code>, <code>pnpm --filter mobile lint</code>, and the full test suite (338 tests, 35 suites) all pass. Tests that asserted on now-removed visible text (<code>getByText(&#39;Send&#39;)</code>, <code>getByText(/via /)</code>) switched to <code>getByLabelText</code>, matching what a screen-reader user actually gets from an icon-only control.</li><li>✅ Verified on the iOS Simulator, on-device, both light and dark (Settings → Appearance): offline banner icon, iconified mode chips, multiline composer growth (confirmed the field expands and caps at three lines on a long paste, with the focus ring in the accent color), and a full send → on-device reply round trip render correctly in both schemes.</li></ul><hr><h4 id="✅-7-6-—-models-screen-sections-progress-bar-fit-badge" tabindex="-1">✅ 7.6 — Models screen: sections, progress bar, fit badge <a class="header-anchor" href="#✅-7-6-—-models-screen-sections-progress-bar-fit-badge" aria-label="Permalink to &quot;✅ 7.6 — Models screen: sections, progress bar, fit badge&quot;">​</a></h4><p><strong>Goal:</strong> Replace the single concatenated subtitle string (name · size · fit note · download phase · percentage · action hint, all in one line) with a scannable structure.</p><p><strong>Deliverables:</strong></p><ul><li>Installed/Available section split, using a new shared <code>SectionLabel</code> component (promoted out of <code>SettingsScreen</code>, which already had its own identical copy — Connectors will need the same pattern in 7.7).</li><li>A new <code>ProgressBar</code> component renders during an active download, replacing the inline <code>&quot;67% · 1.2 of 3.4 GB&quot;</code> text; the byte-count stays in the subtitle since the badge and bar already cover the percentage.</li><li>A new <code>FitBadge</code> component (good/tight/bad/neutral, mapped from the model&#39;s <code>Fit</code> assessment) replaces the trailing mono label everywhere — install state (<code>Download</code>/<code>Installed</code>/<code>In use</code>), transfer state (percentage/<code>Verifying</code>/<code>Retry</code>), and refusal (<code>Too large</code>, colour-coded red rather than an accent-styled &quot;download anyway&quot;). The badge now names a <em>status</em>; the action it implies moved into the subtitle (e.g. &quot;tap to download anyway&quot;), matching <code>reference.html</code>&#39;s Mixtral row.</li><li><code>ListItem</code> gained an optional <code>footer</code> slot (content below the subtitle, in the same column) so the progress bar can render without overlapping the badge.</li></ul><p><strong>Dependencies:</strong> Task 7.4.</p><p><strong>Review checklist:</strong></p><ul><li>✅ <code>pnpm --filter mobile typecheck</code>, <code>pnpm --filter mobile lint</code>, and the full test suite (339 tests, 35 suites) all pass. Tests that asserted on the old uppercase mono labels (<code>DOWNLOAD</code>, <code>CANCEL</code>, <code>IN USE</code>, <code>RETRY</code>, <code>DOWNLOAD ANYWAY</code>) switched to the new sentence-case badge text; one new test covers the Installed/Available section split.</li><li>✅ Verified on the iOS Simulator, on-device, both light and dark (Settings → Appearance): ran a real download (Llama 3.2 1B) start to finish and watched the badge and progress bar advance together (14% → 98%), then watched the row move from Available into Installed with an <code>Installed</code> badge once the transfer completed. The <code>unsupported</code> fit / <code>Too large</code> badge is covered by a unit test rather than on-device — no catalog model exceeds this simulator&#39;s device memory budget to trigger it live.</li></ul><hr><h4 id="✅-7-7-—-settings-segmented-control-connectors-restructure" tabindex="-1">✅ 7.7 — Settings segmented control + Connectors restructure <a class="header-anchor" href="#✅-7-7-—-settings-segmented-control-connectors-restructure" aria-label="Permalink to &quot;✅ 7.7 — Settings segmented control + Connectors restructure&quot;">​</a></h4><p><strong>Goal:</strong> Fix the two structural gaps <code>reference.html</code> identified: Settings&#39; 3-<code>Toggle</code>-as-radio theme picker, and Connectors being the only screen in the app with no section headers despite having the longest list.</p><p><strong>Deliverables:</strong></p><ul><li>A new <code>SegmentedControl</code> component replaces Settings&#39; Appearance section (three <code>Toggle</code>s standing in for a radio group, each requiring the others to be manually driven back to <code>false</code>) with a real mutually-exclusive control. Active-segment elevation uses <code>theme.shadows.control</code>, not just its fill colour — <code>surfaceRaised</code> equals <code>surfaceSunken</code> in dark mode, so colour alone would leave the selection invisible there.</li><li>Connectors gains section headers (Search/Calendar/Device/Installed, via the shared <code>SectionLabel</code> from 7.6) and status pills (reusing <code>FitBadge</code>&#39;s good/tight/bad/neutral variants for Allowed/Needs review/Blocked/Not asked — the same four-colour mapping, different domain), replacing tap-to-toggle rows with navigation to a new <code>ConnectorDetailScreen</code> (grant state, scope, provider switch for Search, credential field, revoke — folding in <code>SearchSetupScreen</code>&#39;s first-run flow, which is retired as a standalone screen and file). Deliberately stays on the detail screen after granting/revoking/saving instead of navigating back — the pill and available action update in place.</li><li>A <code>chevron-right</code> icon added to the curated set, used on every navigable row across Settings, Connectors, and the Connector Store for affordance consistency. <code>ConnectorInstallScreen</code> now replaces itself with the new connector&#39;s own detail screen on success (<code>navigation.replace</code>), matching what happens after granting any other connector, instead of popping back to a plain list.</li></ul><p><strong>Dependencies:</strong> Task 7.4.</p><p><strong>Review checklist:</strong></p><ul><li>✅ <code>pnpm --filter mobile typecheck</code>, <code>pnpm --filter mobile lint</code>, and the full test suite (344 tests, 35 suites) all pass. <code>SearchSetupScreen.test.tsx</code> retired along with the screen; its coverage (provider switch, URL/key validation, save-and-grant) moved into the new <code>ConnectorDetailScreen.test.tsx</code> (19 tests), alongside the built-in permission-connector flows (OS-permission gating for Calendar/Torch, plain grant for Brightness, install/remove for store connectors) migrated out of <code>ConnectorsScreen.test.tsx</code> (11 tests, now navigation-only).</li><li>✅ Verified visually on the iOS Simulator, both light and dark (dark via <code>xcrun simctl ui ... appearance dark</code>, independent of in-app controls): the segmented control&#39;s active-segment elevation, section labels, status pills, and chevrons all render correctly in both schemes.</li><li>⚠️ On-device <em>interactive</em> navigation into Connectors/<code>ConnectorDetail</code> could not be verified this session — the iOS Simulator stopped responding to content-area taps on the Settings screen specifically (the tab bar stayed responsive throughout), and this persisted through a full app relaunch, a Metro cache clear, and a full simulator reboot. Not reproduced in the automated suite, which drives the identical <code>onPress</code> handlers successfully (real <code>userEvent.press</code> through React Navigation&#39;s actual native-stack, not a stub) — treated as a simulator/tooling issue rather than a code defect, but flagged rather than silently skipped.</li></ul><hr><h4 id="✅-7-8-—-release-assets-app-icon-splash-screen" tabindex="-1">✅ 7.8 — Release assets: app icon + splash screen <a class="header-anchor" href="#✅-7-8-—-release-assets-app-icon-splash-screen" aria-label="Permalink to &quot;✅ 7.8 — Release assets: app icon + splash screen&quot;">​</a></h4><p><strong>Goal:</strong> Replace the stock Expo template assets (<code>android-icon-background</code><code>#E6F4FE</code> — an unrelated blue — and an unreferenced <code>splash-icon.png</code>) with real Sovereign Edge identity assets.</p><p><strong>Deliverables:</strong></p><ul><li>New app icon (<code>assets/icon.png</code>, 1024×1024): the &quot;one gate&quot; mark (a sealed boundary ring, opened at exactly one point, with the companion&#39;s spark inside) — identical path data to <code>Mark.tsx</code> and <code>reference.html</code>&#39;s splash mockup — in clay-on-cream (<code>clay700</code> on <code>grey50</code>, the light-theme accent/surface pair), scaled to 62% of the canvas so it reads clearly once iOS applies its own corner mask.</li><li>Android adaptive-icon layers: <code>android-icon-background.png</code> (solid <code>grey50</code>, replacing the stock blue), <code>android-icon-foreground.png</code> (transparent, mark at 42% of canvas — comfortably inside the ~66/108 safe-zone circle launchers guarantee is visible regardless of mask shape), <code>android-icon-monochrome.png</code> (same mark as a single opaque colour on transparent, for Android 13+ themed icons — the OS reads only the alpha channel and applies its own tint).</li><li>A configured splash screen via the <code>expo-splash-screen</code> plugin (<code>app.json</code>&#39;s legacy <code>splash</code> key doesn&#39;t exist in SDK 57; this is its replacement) — <code>grey50</code> background with a transparent <code>clay700</code> mark in light mode, a separate <code>grey950</code>/<code>clay300</code> pair for <code>dark</code>, matching why <code>semantic.ts</code> splits the accent by scheme in the first place: <code>clay700</code> doesn&#39;t have enough contrast against a dark surface.</li><li>Generated with <code>sharp</code> (SVG→PNG, exact path data, no visual drift from hand-tracing) rather than a rasterizer CLI — none of <code>rsvg-convert</code>, <code>imagemagick</code>, or <code>inkscape</code> were available on this machine, and <code>sharp</code> was already resolvable from the npm registry.</li></ul><p><strong>Dependencies:</strong> Task 7.3 (palette), independent of 7.4–7.7.</p><p><strong>Review checklist:</strong></p><ul><li>✅ <code>pnpm --filter mobile typecheck</code>, <code>pnpm --filter mobile lint</code>, and the full test suite (344 tests, 35 suites) all pass — this task touched no application code, only assets and <code>app.json</code>.</li><li>✅ <code>pnpm prebuild</code> (clean) + a full native rebuild succeeded with the new <code>expo-splash-screen</code> CocoaPod integrated; <code>app.json</code> validated as parseable JSON before rebuilding.</li><li>✅ Verified on the iOS Simulator: the Home Screen icon shows the clay &quot;one gate&quot; mark on cream, replacing the stock blue Expo icon, at native resolution (not a stretched placeholder).</li><li>⚠️ The splash screen&#39;s own transient on-screen frame wasn&#39;t caught by a screenshot (it renders and clears before a <code>launch</code>+<code>screenshot</code> round trip completes) — its correctness rests on <code>app.json</code> parsing validly, the <code>expo-splash-screen</code> plugin resolving and integrating cleanly during prebuild with zero build errors, and the composited light/dark previews (<code>sharp</code>-rendered, mark over each theme&#39;s actual surface colour) checked before installing the assets — not on a live capture of the splash itself.</li></ul><h2 id="related-docs" tabindex="-1">Related Docs <a class="header-anchor" href="#related-docs" aria-label="Permalink to &quot;Related Docs&quot;">​</a></h2><ul><li><a href="./../../../CONCEPT.html">CONCEPT.md</a></li><li><a href="./../../research/0001-concept-and-connector-architecture.html">research 0001</a></li></ul>',72)])])}const u=o(s,[["render",i]]);export{g as __pageData,u as default};
